      'Create a highly detailed and vibrantly colored LEGO version of the Shanghai Bund scene. The foreground features the classic historic Bund buildings, exquisitely recreated with LEGO bricks in Western and Neoclassical architectural facades, including details such as clock towers, domes, and colonnades. LEGO minifigures are strolling along the riverbank, taking photos, and sightseeing, with classic-style LEGO cars parked along the streets. The background features the spectacular Huangpu River, constructed with blue translucent LEGO bricks, with LEGO ferries and sightseeing boats on the river surface. On the opposite bank, the Pudong Lujiazui area is lined with skyscrapers, including the Oriental Pearl Tower, Shanghai Tower, Jin Mao Tower, and the World Financial Center—these ultra-modern LEGO skyscrapers are richly colored and realistically shaped. The sky is bright LEGO blue, dotted with a few white LEGO brick clouds, presenting an overall vibrant and modern visual effect.',
