    sourceId: 'davidwu-gpt-image2-prompts',
    title: 'The original treasures are born in dreams.',
    prompt:
      "Create an original creature based on this object (provided photo). The creature should look like it belongs to a fantasy monster-catching universe, with a cute or cool design influenced by retro Japanese RPG monster art. The image must include:\n  – A full-body view of the creature, inspired by the object's shape, material, or purpose.\n  – A small sphere or capsule at its feet (similar to a Poke Ball), with its design pattern and colors matching the object's appearance—not a standard Poke Ball, but a custom design.\n  – An invented name for the creature, displayed next to or below it. – Its element type (e.g., Fire, Water, Metal, Nature, Electric...), based on the object's core attributes. The illustration should look like it's from a fantasy creature encyclopedia, with clean lines, soft shading, and an expressive, character-driven design.",
