    prompt:
      'Create a Japanese cute-style two-panel manga, arranged vertically, theme: A girl president\'s workday.\n\nCharacter design: Convert the uploaded attachment into a Japanese cute-style cartoon girl, preserving all details from the original image, such as clothing (suit), hairstyle (bright golden yellow), facial features, etc.\n\nFirst panel:\nExpression: Looking aggrieved and dejected, resting chin on one hand\nText bubble: "What do I do! He won\'t take my call! (;´д`)"\nScene: Warm-toned office, American flag behind her, a pile of hamburgers on the desk, a vintage red rotary phone, character on the left side, phone on the right side.\n\nSecond panel:\nExpression: Gritting teeth, furious, face flushed red\nAction: Slamming the desk hard, hamburgers bouncing up\nText bubble: "Hmph! Double the tariffs! Not talking to me is their loss! (`д´)"\nScene: Same as first panel, but in total disarray.\n\nOther notes:\nText uses a clean and cute handwritten font, overall style is cute and fun.\nComposition should be full and vivid, with enough space reserved for text display, with appropriate whitespace.\nImage ratio 2:3.\nOverall colors should be vibrant, emphasizing the cartoon style.',
