    prompt:
      'Create a hand-drawn style infographic card in 9:16 portrait ratio. The card has a clear theme, with a paper-textured beige or off-white background, and the overall design embodies a rustic, warm hand-drawn aesthetic.\n\nAt the top of the card, use bold red-and-black contrasting large brush calligraphy to highlight the title and attract visual focus. All text content uses Chinese calligraphy, with the overall layout divided into 2 to 4 clear sections, each expressing core points in short, refined Chinese phrases. The font maintains the flowing rhythm of calligraphy, both legible and artistic. Leave appropriate whitespace around the edges.\n\nThe card is accented with simple, interesting hand-drawn illustrations or icons, such as characters or symbolic elements, to enhance visual appeal and inspire reader reflection and resonance. The overall layout pays attention to visual balance, with sufficient white space to ensure the image is clean, clear, and easy to read and understand.',
