      'A vertical (3:4) 4K resolution minimalist futurist exhibition poster with an ultra-light cool gray #f4f4f4 background.\n\nAt the center of the poster is a fluid 3D metaball in the shape of a [3D Coca-Cola classic soda bottle], with frosted glass material and fine granular noise texture. Fluid gradient: Coca-Cola red #E41C23 → pearl white #FFFFFF, presenting a silky glass-like quality.\n\nHigh-position softbox diffused lighting, casting long and soft colored shadows with faint halos.\n\nThe fluid overlaps the text, and the obscured letters appear with slight Gaussian blur through the frosted glass.\n\n· Main title "Coca-Cola" classic red logo positioned in the center, partially obscured by the fluid element; the obscured letters appear with slight Gaussian blur through the frosted glass.\n\n· Subtitle, Modern sans-serif bold all-caps pure black font: "TASTE THE FEELING" positioned below the main title, also partially covered by the fluid with blur effect, while the rest remains sharp.\n\nOverall clean white space, balanced composition, sharp focal points, HDR high dynamic range.',
    description: 'Replace [3D Coca-Cola classic soda bottle] with other objects for different themes.',
    coverUrl: 'https://cdn.jsdelivr.net/gh/davidwuw0811-boop/awesome-gpt-image2-prompts@main/images/92.png',
