    title: 'Information Graphic Design',
    prompt:
      '{"type":"infographic poster","style":"cute flat vector illustration, cozy, warm, soft shading, {argument name=\\"color palette\\" default=\\"pastel Morandi colors, soft pinks, purples, and warm tones\\"}","character":"{argument name=\\"character description\\" default=\\"young woman with shoulder-length brown hair wearing a pinkish-purple shirt\\"}","layout":{"structure":"4 rows, 3 columns. Top row is a merged header. Rows 2-4 contain 9 individual panels.","header":{"title":"{argument name=\\"main title\\" default=\\"You\'re not feeling well?\\"}","subtitle":"{argument name=\\"subtitle\\" default=\\"Eight ways to make you better in a moment.\\"}","sub_subtitle":"It\'s for you. Come and see it.","visual":"character hugging herself, surrounded by yellow sparkles and hearts"},"grid_panels":[{"id":1,"title":"1. Deep breaths","text":"Regulate the nerves, ease the tension.","visual":"character with eyes closed, smiling, surrounded by clouds"},{"id":2,"title":"2. Outdoor walks","text":"Touch nature, calm your heart.","visual":"character walking outdoors among green trees and bushes"},{"id":3,"title":"3. Writing emotional journals","text":"Write down the trouble, the brain will be easier.","visual":"character sitting at a desk writing in a notebook with a pen, floating hearts"},{"id":4,"title":"4. Hold yourself.","text":"Give yourself warmth and comfort.","visual":"character hugging herself with eyes closed, floating hearts"},{"id":5,"title":"5. Listen to music","text":"Let the melody of ease heal the heart.","visual":"character wearing large white headphones, eyes closed, floating colorful music notes"},{"id":6,"title":"6. Taking up complaints","text":"Share your troubles, let the pressure release.","visual":"character holding a smartphone, talking to another similar-looking girl, floating hearts"},{"id":7,"title":"Look at the sky.","text":"Feel the sky\'s vast, make it feel better.","visual":"character looking up at a blue sky with white clouds and sparkles"},{"id":8,"title":"8. Meditology","text":"Focus on breathing, and find the peace of mind.","visual":"an open notebook, a pen, and a pink flower on a desk"},{"id":9,"title":"none","text":"{argument name=\\"footer text\\" default=\\"Retransmit the collection, take care of yourself every day!\\"}","visual":"character sitting cross-legged in a meditation pose, eyes closed, with a glowing halo behind her head"}]}}',
