    title: 'Information Graphic Design',
    prompt:
      'Please generate a Chinese fitness information map, entitled: [xx]. Require that this map be professional and practical and suitable for adults as a training reference. Default is for healthy adults without serious injuries; default training is for “increased muscle + basic strength” if no additional information is provided; default training level is “newer to mid-level”; default training scene is for “normal gymnasium” and default single training time is controlled within 40-60 minutes; and decide automatically on the type of output: 1) if [the subject of training] is a muscle or body (e.g. pectrob, breath, biceps, abdominal, shoulder, leg, etc.) and output a “information on the Department\'s training programme”. 2) If [the subject of training] is an action or skill target (e.g., e.g., e.g., upward, push, double-bard, deep crouch, etc.), please output an “action unlocked/elemental training programme information map.” The whole map is based on a clear, modern, professional, easy-to-read Chinese style of information map, vertical layout, visual simplicity, focus, and suitable for social media sharing or training reference cards. Do not write a growth story, each module is presented in a short, concise sentence, and digital information must be visible. This information map must contain the following: [A. Title] - Head title: Write directly [the training programme]/ unlocked by subheadline: Auto-complement applicable population, targets, training scenes, and suggested time frames, for example:The main objective of this training is: What is the main target (influencing/power/skill unlocking/ core control, etc.) - The focus of this training is stimulation or capability enhancement [C. Hotspot] gives 2-4 warm-up recommendations, which are simple and simple, such as: - Dynamic activity - Target muscle activation - Lightweight preheat group Each can be accompanied by a description [D. Main Training Area] This is the core part, and please list 4-6 main training actions. - Action name - Training / Targeted part - Group number x number (or time) - RIR Recommendation - Break time per group - Key points of action (1-2 articles) - Common error(1 fine) - Ensure that action is well organized: - Co-ordinated action, then isolated action - Total training is moderate - New hands do not arrange over-extension training - Active RIR 1-3 - Isolated action suggests RIR 0-2 - In the case of abdominal or core type action, use "seconds/ times" - If skills type action, give priority to "Pre-Capacity action + Transition action + Target action attempt" [E.] Step / Unlock Logic Zone) Automatically generated by theme: - If a muscle training: Write "How to incrementally overload" , e.g., after reaching the numerical limit, then increase, priority guaranteed action standards, etc. - If an action unlocks: Write " Phased step path" , e.g. from the shin, shoulder-tip, centrifuge training, bullet-band aids, to standard action completion [F. Alternative action area] give 2-3 alternative actions, applicable to: - No device - current capacity of family training - Some actions cannot be done [G. Implementation Reminder Zone] - Action standards take precedence over weight - do not practice exhaustion in each group - 48-72 hours between recommendations and the muscles - Pain does not equal normal strength - Training can be reduced appropriately when sleep is not enough [H. Restoring the suggested area] Simplicity: - Restoring focus after training - Protein / Sleep / Resting the interval - 1 sentence of risk alert (if apparent pain should stop and be assessed) [I. Visual design requirements] - All in one page of information map in Chinese - Modern style, cleanness, professional, fitness - Use modular card layout - Focus numbers (group, number, RIR, rest) can be highlighted - A simple body of human muscle icons, dumbbell, bell, bell,Quote a small top-up icon - Colours are kept high, clean, moving - Chinese text must be clear, accurate, readable - avoid excessive decoration, emphasis on practicality and execution, and end up with " A complete picture of the content " , not just the normal paragraph text.',
