      "Create a 10-x10 grid containing 100 different fantastic RPG items, which are republished in classic pixel art style (16 or 32 elixie graphic aesthetics, reminiscent of the SNES/GBA era. Each item should appear in its separate square tiles with a short and clear label on its bottom. Keep the grid clean in the white background. Make each object visible and spell correctly each. Use clear pixel edges, limited palettes of each elixie map, and subtle shaking for shadows. Use these lines: Line 1: swords and blades, line 2: shield and armor, line 3: bows, screech and long-range weapons, line 4: law rods, wands and magic focus Line 5: medicine: water, magic focusPsychics and flask bottles Line 6: scrolls, scripts and magic arts Book Line 7: rings, amulets and magic gadget Line 8: helmets, crowns and headdresss Line 9: keys, relics and mission objects Line 10: gems, symbols and production materials displaying each brick as a map of the fairies in the middle of the clean background square, reproducing as a classic inventory icon, as you see in the Fantasia RPG menu. Keep the whole style, consistency and remixed RPGs -- attractive, rich in detail and easily identifiable in small sizes. [English] Create a 10 × 10 grid of 100 different fantasy RPG items rendered in classic pixel art style (16-bit or 32-bit sprite aesthetic, reminiscent of SNES/GBA-era JRPGs). Each item should appear in its own square tile with a short clear label underneath. Keep the grid neat on a white background. Make every item visually distinct and every label correctly spelled. Use crisp pixel edges, limited palette per sprite, and subtle dithering for shading. Use these row themes: Row 1: swords and blades Row 2: shields and armor Row 3: bows, crossbows, and ranged weapons Row 4: staves, wands, and magical foci Row 5: potions, elixirs, and flasks Row 6: scrolls, tomes, and spellbooks Row 7: rings, amulets, and enchanted trinkets Row 8: helmets, crowns, and headgear Row 9: keys, relics, and quest items Row 10: gems, runes, and crafting materials Show each tile as a centered item sprite on a clean background square, rendered as a classic inventory icon — the kind you'd see in a fantasy RPG menu. Keep the overall style consistent, cohesive, and reminiscent of beloved retro fantasy RPGs — charming, detailed, and instantly readable at small sizes.",
