    prompt:
      "You are a high-end physical-push poster generation system, which aims to generate an Apple-style high-level science-preference visual poster for rare animals, insects, reptiles, mammals, or other small human beings. Overall vision direction: A 9:16 vertically advanced science-pup poster with very simple, white, clean, modern, Apple-style products in the language of the poster. Background should be white or very pale, with a large amount of white. The overall design should be high-level, restraining, visual impact, and scientific display. Core design principles: 1. Subject animals must be extremely zoomed up to become the strongest visual centre of the picture. 3. Posters are kept to a minimum and avoid overcrowding. 4. The bottom information area is separated by a very simple four columns of icon + title + short description. 6. Text layout is like a high-end publishing session with visualization, large titles, subheading restraint, small text and clarity. 7. Style key words: Apple-inspiced, premium editoral, pure white background, hero subject, clean typogrampy, Main distribution: {Specific name of English} Main distribution: {Specific area} Central and Lower Central is the main visualization: Generate a super-high, real, strong-stereotype {Specific name of Chinese). The subject should occupy 50 to 70% of the visual area of the image. The master gesture should be displaying, power or recognition. Keep the white background and not add a complex natural environment.For example, branches, rocks, snow, sand or wood, but must be simple. The subject should have real shadows so that it can be placed in the picture like a photo of a high-level product. Bottom information area: display of the science-plug information in four very simple information columns. Each column contains: a line icon, a coloured subheading 1 to 3 lines of short text lines separated by a very light ash vertical line between the columns. No card box, no rounded background, no large area colour column. Four information columns: column 1: Title: {Cight feature 1 title} Description: {Focus feature 1 short description} column 2: Title: {Elemental feature 2 title} Description: {Elemental feature 2 short description} column 3: Title: {Fominence feature 2 short description}{Custural feature 3] Description: {Focus feature 3 short description} Column 4: Title: {Focus feature 4 short description} Description: {Focus feature 4 short description} Bottom sentence: {A high-level, restrained, memory-based science-based summary} Fonts and layout: Chinese title using large black, high-level, steady, powerful fonts. Subtitles use grey, medium-term word numbers, slightly wide word-spaced. English name: grey, concise modern. Text in plain and modern Chinese fonts, keeping readable. All words must be in a sufficiently breathing sense. Colour: Background: white, very light, light light light. Main title: black or dark graphy. Subtitles and plain text: black or dark graphy.The four message headings at the bottom can be coloured with low saturation: warm brown, cold blue, pine green, purple, orange. Colour is used only for icon and small headings, not large-scale colouring. Image quality: 2K high-resolution, clear details, sharp body, real light. Main texture must be credible, such as hair, spectros, crust, skin wrinkle, feather or stripe. Avoid deformation, error body, incorrect anatomy structure, blurry body, low-quality profile, plastic sense, cartoon sense. Banner: do not use yellow old paper background. Do not use complex information image grids. Do not use round card cards. Do not use thick border frames. Do not use large area decorative graphics. Do not add non-observed logo. Do not let the text overwhelm the subject. Do not make the bottom information area overcrowded. Do not show children's general, cartoon, low-end display. Final output: Generate an Apple Winds Panty poster that is 9:16 vertical, advanced, clean, visualized.",
