    title: 'Image Template - Animated Map',
    prompt:
      'type: illustrated map infographic | style: {argument name="art style" default="watercolor and ink hand-drawn illustration on vintage parchment"} | text: {argument name="city name" default="Chengdu"}  {argument name="map title" default="Eating a cargo and walking away."} | mascot: cartoon red chili pepper wearing sunglasses and giving a thumbs up | border: {argument name="border decoration" default="vine of green leaves and red chili peppers"} | background: textured beige parchment paper with yellow roads, blue rivers, and green park areas | title: The landmarks are the main source of information for the local media, and the local media are the main source of information on the situation. The only thing that matters is the fact that the world is a small country, and the world is a small country, and the world is a small country, and the world is a small country, and it\'s a small country, and it\'s a small country, and it\'s a big country, and it\'s a big country. ♪ 2 clocks, 3 spring, 3 spring, 3 ♪ 4 narrow alleys, 3 cannons 5 build Lou Yee-mothers\' eggs, 6 jalin, little dragon pot 7 ♪ ♪ ♪ ♪ ♪ ♪ ♪ ♪ ♪ ♪ ♪ ♪ ♪ Cham, ♪ Cham, Cham, Cham, Cham, Cham, Cham, Cham, Cham, Cham, Cham, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, Pa, P-P, P-P, P-P But I\'m not sure what I\'m talking about, but I\'m not sure if I\'m gonna be able to do it, but I\'m gonna be able to do it.♪ with a red chili pepper icon ♪',
